package cl.almejo.vsim.core.geometry;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalInt;

/**
 * What {@link Snapping#solve} needs: the lines of the moving set per axis (before the move), the raw delta the pointer
 * asks for, the candidate targets, the magnet's reach in grid units, the grid-line spacing when snapping to grid lines
 * is on (its candidates are generated by the solver) and the moving set's box (for the tie-break by distance).
 */
public record SnapInput(Map<Axis, List<Double>> movingLines, int rawDeltaX, int rawDeltaY,
                        List<SnapTarget> targets, int thresholdUnits, OptionalInt gridLineSpacing,
                        Optional<Bounds> movingBox) {

    public SnapInput {
        movingLines = Map.copyOf(movingLines);
        targets = List.copyOf(targets);
    }
}
